#include <iostream>

class StepCounter {
    int steps;
public:
    explicit StepCounter(int s = 0) : steps(s) {}

    // Prefix increment (++counter): modifies and returns reference
    StepCounter& operator++() {
        ++steps;
        return *this;
    }

    // Postfix increment (counter++): saves old copy, modifies, returns copy
    StepCounter operator++(int) {
        StepCounter temp = *this;
        ++steps;
        return temp;
    }

    // Non-member friend stream insertion operator
    friend std::ostream& operator<<(std::ostream& os, const StepCounter& sc) {
        os << "StepCounter(" << sc.steps << ")";
        return os;
    }
};

int main() {
    StepCounter c(10);
    std::cout << "Initial: " << c << "\n";
    std::cout << "Prefix:  " << ++c << "\n";
    std::cout << "Postfix: " << c++ << "\n";
    std::cout << "Current: " << c << "\n";
    return 0;
}

#include <iostream>
#include <cstddef>

class ManagedBuffer {
    int* buffer;
    size_t count;
public:
    // Explicit constructor prevents accidental implicit numeric conversion
    explicit ManagedBuffer(size_t sz) : count(sz), buffer(new int[sz]()) {}

    ~ManagedBuffer() {
        delete[] buffer; // Must pair new[] with delete[]
    }

    // Subscript operator: non-const for lvalue modification
    int& operator[](size_t idx) { return buffer[idx]; }
    // Subscript operator: const for read-only access
    int operator[](size_t idx) const { return buffer[idx]; }

    // Explicit conversion operator to bool: valid if count > 0
    explicit operator bool() const { return count > 0; }

    size_t size() const { return count; }
};

int main() {
    ManagedBuffer buf(3);
    buf[0] = 42;
    buf[1] = 84;
    buf[2] = 126;

    if (buf) { // Contextual explicit conversion to bool
        std::cout << "Buffer contains " << buf.size() << " items: ";
        for (size_t i = 0; i < buf.size(); ++i) {
            std::cout << buf[i] << (i + 1 == buf.size() ? "" : ", ");
        }
        std::cout << "\n";
    }
    return 0;
}

#include <iostream>

class Complex {
    double real;
    double imaginary;
public:
    explicit Complex(double r = 0.0, double i = 0.0) : real(r), imaginary(i) {}

    Complex operator+(const Complex& rhs) const {
        return Complex(real + rhs.real, imaginary + rhs.imaginary);
    }

    Complex operator-(const Complex& rhs) const {
        return Complex(real - rhs.real, imaginary - rhs.imaginary);
    }

    // Algebraic complex multiplication: (a + bi)(c + di) = (ac - bd) + (ad + bc)i
    Complex operator*(const Complex& rhs) const {
        return Complex(real * rhs.real - imaginary * rhs.imaginary,
                       real * rhs.imaginary + imaginary * rhs.real);
    }

    bool operator==(const Complex& rhs) const {
        return (real == rhs.real) && (imaginary == rhs.imaginary);
    }

    bool operator!=(const Complex& rhs) const {
        return !(*this == rhs);
    }

    friend std::ostream& operator<<(std::ostream& os, const Complex& c) {
        os << '(' << c.real << ", " << c.imaginary << ')';
        return os;
    }
};

int main() {
    Complex x(4.3, 8.2);
    Complex y(3.3, 1.1);

    Complex sum = x + y;
    Complex diff = x - y;
    Complex prod = x * y;

    std::cout << "x: " << x << "\n";
    std::cout << "y: " << y << "\n";
    std::cout << "x + y = " << sum << "\n";
    std::cout << "x - y = " << diff << "\n";
    std::cout << "x * y = " << prod << "\n";
    std::cout << "x == y: " << (x == y ? "true" : "false") << "\n";
    std::cout << "x != y: " << (x != y ? "true" : "false") << "\n";
    return 0;
}
